# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MUTLAK DEĞER FONKSİYONUNUN PARÇALI GÖSTERİMİ VE GRAFİĞİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">m(x) = |x - 2| + 1 GRAFİĞİ VE TEPE NOKTASI</text>\n  <line x1="40" y1="190" x2="310" y2="190" stroke="#64748b" stroke-width="1.5"/>\n  <line x1="110" y1="65" x2="110" y2="225" stroke="#64748b" stroke-width="1.5"/>\n  <line x1="190" y1="70" x2="190" y2="220" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="4,3"/>\n  <polyline points="90,85 190,165 290,85" fill="none" stroke="#2563eb" stroke-width="3"/>\n  <circle cx="190" cy="165" r="5" fill="#dc2626"/>\n  <text x="190" y="182" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">T(2, 1)</text>\n  <text x="235" y="78" font-size="10" font-weight="bold" fill="#475569">Simetri Ekseni: x = 2</text>\n  <text x="98" y="170" font-size="10" fill="#0f172a">1</text>\n  <text x="187" y="205" font-size="10" fill="#0f172a">2</text>\n  <text x="35" y="226" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Görüntü Kümesi: [1, +∞) · En küçük değer: 1</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">KRİTİK NOKTA VE PARÇALI FONKSİYON YAZIMI</text>\n  <text x="375" y="92" font-size="11" font-weight="bold" fill="#14532d">1. Adım (Kritik Nokta): Mutlak değer içini sıfır yapan</text>\n  <text x="385" y="108" font-size="10.5" fill="#166534">değer bulunur: ax + b = 0  ⇒  x = -b / a (Tepe apsisi).</text>\n  <text x="375" y="132" font-size="11" font-weight="bold" fill="#14532d">2. Adım (Sağ ve Sol Kollar): m(x) = |x - 2| + 1 için</text>\n  <text x="385" y="152" font-size="11" font-weight="bold" fill="#1e40af">• x ≥ 2 ise (içerisi ≥ 0): m(x) = (x - 2) + 1 = x - 1</text>\n  <text x="385" y="172" font-size="11" font-weight="bold" fill="#b91c1c">• x &lt; 2 ise (içerisi &lt; 0): m(x) = -(x - 2) + 1 = -x + 3</text>\n  <text x="375" y="198" font-size="10.5" fill="#14532d">• x = 2 doğrusuna göre simetriktir; (-∞, 2] aralığında azalan,</text>\n  <text x="383" y="214" font-size="10.5" fill="#14532d">[2, +∞) aralığında artandır; R\'de bire bir DEĞİLDİR.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DOĞRUSAL FONKSİYONLARLA DENKLEM VE EŞİTSİZLİK ÇÖZÜMÜ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">GRAFİKSEL KESİŞİM VE BAŞABAŞ NOKTASI</text>\n  <line x1="40" y1="195" x2="310" y2="195" stroke="#64748b" stroke-width="1.5"/>\n  <line x1="65" y1="65" x2="65" y2="220" stroke="#64748b" stroke-width="1.5"/>\n  <line x1="65" y1="180" x2="290" y2="80" stroke="#2563eb" stroke-width="2.5"/>\n  <line x1="65" y1="110" x2="290" y2="165" stroke="#dc2626" stroke-width="2.5"/>\n  <circle cx="172" cy="133" r="5" fill="#16a34a"/>\n  <line x1="172" y1="133" x2="172" y2="195" stroke="#16a34a" stroke-width="1.5" stroke-dasharray="4,3"/>\n  <text x="172" y="210" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">x = x0</text>\n  <text x="255" y="78" font-size="10.5" font-weight="bold" fill="#1d4ed8">y = f(x)</text>\n  <text x="255" y="180" font-size="10.5" font-weight="bold" fill="#b91c1c">y = g(x)</text>\n  <text x="35" y="228" font-size="10.5" fill="#78350f">• x &lt; x0 iken f(x) &lt; g(x) | x &gt; x0 iken f(x) &gt; g(x)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">CEBİRSEL VE GRAFİKSEL ÇÖZÜM KURALLARI</text>\n  <text x="375" y="92" font-size="11" font-weight="bold" fill="#581c87">• f(x) = g(x) Denklemi:</text>\n  <text x="385" y="108" font-size="10.5" fill="#6b21a8">İki doğrunun kesişim noktasının apsisini (x0) verir.</text>\n  <text x="375" y="132" font-size="11" font-weight="bold" fill="#581c87">• f(x) &gt; g(x) Eşitsizliği:</text>\n  <text x="385" y="148" font-size="10.5" fill="#6b21a8">f(x) grafiğinin g(x) grafiğinin ÜSTÜNDE kaldığı x aralığıdır.</text>\n  <text x="375" y="172" font-size="11" font-weight="bold" fill="#581c87">• Eşitsizlikte Negatif Sayıyla Çarpma/Bölme:</text>\n  <text x="385" y="188" font-size="10.5" font-weight="bold" fill="#b91c1c">Eşitsizliğin her iki tarafı negatif (a &lt; 0) bir sayıyla</text>\n  <text x="385" y="204" font-size="10.5" font-weight="bold" fill="#b91c1c">çarpılır veya bölünürse eşitsizlik YÖN DEĞİŞTİRİR!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MUTLAK DEĞERLİ DENKLEM VE EŞİTSİZLİKLERİN ÖZET TABLOSU</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">1. MUTLAK DEĞERLİ DENKLEMLER: |f(x)| = c</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#155e75">• c &gt; 0 ise (İki daldan çözüm gelir):</text>\n  <text x="45" y="114" font-size="11" font-weight="bold" fill="#0e7490">f(x) = c   veya   f(x) = -c</text>\n  <text x="35" y="140" font-size="11" font-weight="bold" fill="#155e75">• c = 0 ise (Tek kök / Tepe noktası):</text>\n  <text x="45" y="158" font-size="11" font-weight="bold" fill="#0e7490">|f(x)| = 0  ⇒  f(x) = 0</text>\n  <text x="35" y="184" font-size="11" font-weight="bold" fill="#b91c1c">• c &lt; 0 ise (Çözüm kümesi boş kümedir):</text>\n  <text x="45" y="202" font-size="11" font-weight="bold" fill="#991b1b">|f(x)| = -5  ⇒  ÇK = ∅ (Mutlak değer negatif olamaz!)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">2. MUTLAK DEĞERLİ EŞİTSİZLİKLER (c &gt; 0 İÇİN)</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#881337">• Küçüktür / Küçük Eşittir Durumu (İç Aralık):</text>\n  <text x="385" y="116" font-size="11.5" font-weight="bold" fill="#15803d">|ax + b| ≤ c  ⇔  -c ≤ ax + b ≤ c</text>\n  <text x="385" y="134" font-size="10.5" fill="#9f1239">(Tolerans / hata payı problemlerinde kullanılır.)</text>\n  <text x="375" y="162" font-size="11" font-weight="bold" fill="#881337">• Büyüktür / Büyük Eşittir Durumu (İki Dış Bölge):</text>\n  <text x="385" y="182" font-size="11.5" font-weight="bold" fill="#1e40af">|ax + b| ≥ c  ⇔  ax + b ≥ c  veya  ax + b ≤ -c</text>\n  <text x="375" y="212" font-size="10.5" font-weight="bold" fill="#881337">• Üçgen Eşitsizliği: |x + y| ≤ |x| + |y|</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
